<?php
declare(strict_types=1);
require_once __DIR__.'/../lib/helpers.php';require_once __DIR__.'/../lib/admin.php';require_once __DIR__.'/../lib/notifications.php';send_cors_headers();$context=require_admin('products.review');$db=get_db();$method=$_SERVER['REQUEST_METHOD']??'GET';if($method==='GET'){$claims=$db->query('SELECT c.*,v.display_name,f.scan_status FROM sustainability_claims c JOIN vendors v ON v.id=c.vendor_id JOIN file_assets f ON f.id=c.evidence_file_id ORDER BY c.created_at DESC LIMIT 300');$certs=$db->query('SELECT c.*,v.display_name,f.scan_status FROM vendor_certificates c JOIN vendors v ON v.id=c.vendor_id JOIN file_assets f ON f.id=c.file_asset_id ORDER BY c.created_at DESC LIMIT 300');json_response(200,['success'=>true,'claims'=>$claims->fetchAll(),'certificates'=>$certs->fetchAll()]);}if($method==='POST'){$body=get_json_body();$kind=trim((string)($body['record_type']??''));$id=trim((string)($body['id']??''));$decision=trim((string)($body['decision']??''));$notes=trim((string)($body['notes']??''));if(!in_array($decision,['approve','reject','request_evidence'],true)||($decision!=='approve'&&mb_strlen($notes)<10))json_response(422,['success'=>false,'message'=>'Decision and detailed notes are required.']);if($kind==='claim'){$stmt=$db->prepare('SELECT c.*,f.scan_status FROM sustainability_claims c JOIN file_assets f ON f.id=c.evidence_file_id WHERE c.id=:id');$stmt->execute(['id'=>$id]);$record=$stmt->fetch();if(!$record)json_response(404,['success'=>false,'message'=>'Claim not found.']);if($decision==='approve'&&$record['scan_status']!=='clean')json_response(422,['success'=>false,'message'=>'Evidence must pass security scanning.']);$status=['approve'=>'approved','reject'=>'rejected','request_evidence'=>'evidence_requested'][$decision];$db->prepare('UPDATE sustainability_claims SET review_status=:status,public_status=:public,reviewed_by=:admin,reviewed_at=UTC_TIMESTAMP(),updated_at=UTC_TIMESTAMP() WHERE id=:id')->execute(['status'=>$status,'public'=>$status==='approved'?'published':'hidden','admin'=>$context['admin']['id'],'id'=>$id]);create_notification('vendor',$record['vendor_id'],'claim_review','Sustainability claim review','Your claim is now '.str_replace('_',' ',$status).'.',null,['claim_id'=>$id,'notes'=>$notes]);audit_event('admin.claim_'.$decision,'sustainability_claim',$id,['notes'=>$notes]);json_response(200,['success'=>true,'message'=>'Claim review saved.','status'=>$status]);}if($kind==='certificate'){$stmt=$db->prepare('SELECT c.*,f.scan_status FROM vendor_certificates c JOIN file_assets f ON f.id=c.file_asset_id WHERE c.id=:id');$stmt->execute(['id'=>$id]);$record=$stmt->fetch();if(!$record)json_response(404,['success'=>false,'message'=>'Certificate not found.']);if($decision==='approve'&&$record['scan_status']!=='clean')json_response(422,['success'=>false,'message'=>'Certificate must pass security scanning.']);$status=['approve'=>'verified','reject'=>'rejected','request_evidence'=>'evidence_requested'][$decision];$db->prepare('UPDATE vendor_certificates SET verification_status=:status,updated_at=UTC_TIMESTAMP() WHERE id=:id')->execute(['status'=>$status,'id'=>$id]);create_notification('vendor',$record['vendor_id'],'certificate_review','Certificate review','Your certificate is now '.str_replace('_',' ',$status).'.',null,['certificate_id'=>$id,'notes'=>$notes]);audit_event('admin.certificate_'.$decision,'vendor_certificate',$id,['notes'=>$notes]);json_response(200,['success'=>true,'message'=>'Certificate review saved.','status'=>$status]);}json_response(422,['success'=>false,'message'=>'Invalid record type.']);}json_response(405,['success'=>false,'message'=>'Method not allowed.']);
